-- Chemistry course record. Safe to run more than once.
alter table public.courses add column if not exists video_url text;

insert into public.courses (slug, title, subject, credits, focus)
values ('chemistry', 'Chemistry', 'Science', 1.0, $j$Chemistry is a one credit laboratory science course that helps students understand the matter God created, how it is built, how it behaves and how it changes. Students study matter and its properties, measurement and significant figures, safe scientific investigation, dimensional analysis and density, atomic structure and isotopes, electron configuration, the periodic table and periodic trends, ionic and covalent bonding, naming compounds, molecular shape and polarity, chemical reactions and balancing equations, the mole, stoichiometry, limiting reactants and percent yield, states of matter and phase changes, the gas laws, solutions and molarity, energy and thermochemistry, acids and bases and pH, reaction rates and equilibrium, oxidation and reduction, nuclear chemistry, organic chemistry and stewardship of creation. Each lesson connects to Scripture in the King James Version and to honest, careful, safe science. The course includes six units, lesson checks, unit quizzes, assessments, discussions and a final investigation and exam. Any hands on activity at home uses safe household materials only with adult permission and supervision.$j$)
on conflict (slug) do nothing;
